root.script:
// self is the script element - its parent is root
var rootElement = Element.new(0)  // Root is always 0

// Counter for events  
var eventCount = 0

// Listen for keypress events
document.addEventListener("keypress", Fn.new { |event|
    eventCount = eventCount + 1

    // Create a text node with the key
    var textNode = document.createText(event["key"] + " ")

    // Create a colored box for this key
    var keyBox = document.createElement("inline px-2 py-1 m-1 bg-blue-600 text-white")

    // Append text to box
    keyBox.append(textNode)

    // Append box to root
    rootElement.append(keyBox)
})
